<?php
namespace Ishep\Services;
use PDO;use Ishep\Repositories\UserRepository;use Ishep\Repositories\PasswordResetRepository;use Ishep\Support\Logger;
final class PasswordResetService { public function __construct(private PDO $db,private UserRepository $users,private PasswordResetRepository $tokens,private Logger $logger,private array $mail){} public function request(string $email,string $base):void{$u=$this->users->byEmail($email);if(!$u)return;$token=bin2hex(random_bytes(32));$this->tokens->store($email,hash('sha256',$token));if($this->mail['driver']==='log')$this->logger->log('info','Development password reset URL',['reset_url'=>$base.'/reset-password/'.$token.'?email='.rawurlencode($email)]);} public function reset(string $email,string $token,string $password):bool{if(!$this->tokens->valid($email,$token))return false;$u=$this->users->byEmail($email);if(!$u)return false;$this->db->beginTransaction();try{$this->users->password((int)$u['id'],password_hash($password,PASSWORD_DEFAULT));$this->tokens->delete($email);$this->db->commit();return true;}catch(\Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw$e;}} }
